using UnityEditor;using System;using System.IO;using System.Linq;using UnityEngine;
namespace Xinghai.MapEditor.Editor {public static class PackageM12Proof {public static void Run(){try{var colors=(Newtonsoft.Json.Linq.JArray)Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText("Assets/M12MaterialContract/assembled.xhmaterials.json"))["colors"];var materials=AssetDatabase.LoadAllAssetsAtPath("Assets/M12MaterialContract/assembled.fbx").OfType<Material>().ToArray();int doubleSided=0;foreach(var c in colors){if(!c.Value<bool>("doubleSided"))continue;doubleSided++;var m=materials.Single(x=>x.name==c.Value<string>("colorId"));string expected="Xinghai/Exchange Double Sided"+(c.Value<string>("alphaMode")=="BLEND"?" Blend":"");if(m.shader.name!=expected||ShaderUtil.ShaderHasError(m.shader))throw new Exception("Double-sided shader invalid "+m.name);}foreach(var name in new[]{"Xinghai/Exchange Double Sided","Xinghai/Exchange Double Sided Blend"}){var shader=Shader.Find(name);if(shader==null||ShaderUtil.ShaderHasError(shader))throw new Exception("Exchange shader compilation failed "+name);}if(doubleSided==0)throw new Exception("Double-sided fixture missing");File.WriteAllText("../m12/shader-package-check.json",new Newtonsoft.Json.Linq.JObject{{"passed",true},{"doubleSidedMaterials",doubleSided},{"shadersChecked",2},{"note","Bindings and shader compiler only; transparent sorting visual acceptance remains separate"}}.ToString());Directory.CreateDirectory("../../release");var runtime=Directory.GetFiles("Assets/XinghaiMap/Runtime").Where(p=>!p.EndsWith(".meta")&&!p.EndsWith("ProofPlayer.cs")).Select(p=>p.Replace('\\','/'));var editor=new[]{"BakeWindow","MapBaker","BakeJournal","SourceReader","PlacementIdentity","NativeAssetMaterials"}.Select(n=>"Assets/XinghaiMap/Editor/"+n+".cs");AssetDatabase.ExportPackage(runtime.Concat(editor).ToArray(),"../../release/星骸地图团结插件-M1.2.unitypackage",ExportPackageOptions.Default);Debug.Log("XH_PACKAGE_PASS");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}}
